/* 
* Ce node permet d'adapter le format json produit 
* par l'ESP à celui attendu par la map 
*/

//http://stevesnoderedguide.com/node-red-functions
var nmsg = { // on cree un nouveau message nodered
    topic: msg.topic  // on garde le vieux topic
    };

// Gestion de l'occupation
var busy;

/*
if (msg.payload.piscine.occuped === false)
  busy = "battery-empty";
else
  busy = "battery-full";
*/
busy = "battery-full";

var hsc;
if (msg.payload.piscine.hotspot === false)
  hsc = "Blue";
else
  hsc = "Red";

var poolId = msg.payload.info.ident;   // ex: "P_22411036"
var userId = msg.payload.info.user;    // ex: "noe"

// Construction de l'URL pour accéder à la piscine
var link = "https://waterbnb-fn411036.onrender.com/open?idswp=" + poolId + "&idu=" + userId;

// Construction du HTML à mettre dans 'description'
// On utilise target='_blank' pour ouvrir le lien dans un nouvel onglet
var htmlDescription = "<b>Piscine " + poolId + "</b><br/>" +
  "Temp: " + msg.payload.status.temperature + "°C<br/>" +
  "<a href='" + link + "' target='_blank'>Réserver/Accéder</a>";


nmsg.payload = { // on modifie/adapte la payload
    layer : "swimming pools",
    name : msg.payload.info.ident,
    description: htmlDescription,
    unit:"C",
    color: "#000",
    value: msg.payload.status.temperature,
    lat: msg.payload.location.gps.lat,
    lon: msg.payload.location.gps.lon,
    iconColor : hsc,
    //icon: "male",
    icon: busy    
}

return nmsg;

