return msg;

// On récupère flow.tempUserId
var tempId = flow.get("tempUserId") || "";

// On le copie dans flow.userId si non vide
if (tempId.trim() !== "") {
    flow.set("userId", tempId.trim());
    node.status({fill:"green",shape:"dot",text:"User ID validé : " + tempId});
} else {
    node.status({fill:"red",shape:"ring",text:"Aucun User ID saisi !"});
}
return msg;

// Comme précédemment, on adapte le JSON pour la worldmap

// On récupère le userId validé
var userId = flow.get("userId") || "";

// Récupérer l'ID de la piscine
var poolId = msg.payload.info.ident || "P_??";

// Couleur d'icône si hotspot ou non
var hsc = (msg.payload.piscine.hotspot === false) ? "Blue" : "Red";

// Occupé ou pas => icône
var busy = "battery-full";
// if (msg.payload.piscine.occuped === false) busy = "battery-empty";

var htmlDescription;
if (userId === "") {
    // Si pas validé => on n'affiche pas de lien
    htmlDescription = "<b>Piscine " + poolId + "</b><br/>" +
        "Temp : " + msg.payload.status.temperature + " °C<br/>" +
        "<em>Veuillez saisir et valider votre User ID pour réserver</em>";
} else {
    // user ID validé => on construit le lien
    var link = "https://waterbnb-fn411036.onrender.com/open?idswp=" + poolId + "&idu=" + userId;
    htmlDescription = "<b>Piscine " + poolId + "</b><br/>" +
        "Temp : " + msg.payload.status.temperature + " °C<br/>" +
        "<a href='" + link + "' target='_blank'>Accéder / Réserver</a>";
}

var nmsg = {
    topic: msg.topic,
    payload: {
        layer : "swimming pools",
        name : poolId,
        description: htmlDescription,
        unit: "C",
        color: "#000",
        value: msg.payload.status.temperature,
        lat: msg.payload.location.gps.lat,
        lon: msg.payload.location.gps.lon,
        iconColor: hsc,
        icon: busy
    }
};

return nmsg;
